export function getToolBySlug(slug: string): ToolItem | undefined {
  return TOOLS_CATALOG.find((t) => t.slug === slug);
}

export function getToolsByCategory(category: string): ToolItem[] {
  if (!category || category === "All") return TOOLS_CATALOG;
  return TOOLS_CATALOG.filter(
    (t) => t.category.toLowerCase() === category.toLowerCase()
  );
}

export function searchTools(query: string): ToolItem[] {
  if (!query.trim()) return TOOLS_CATALOG;
  const q = query.toLowerCase().trim();
  return TOOLS_CATALOG.filter(
    (t) =>
      t.name.toLowerCase().includes(q) ||
      t.description.toLowerCase().includes(q) ||
      t.category.toLowerCase().includes(q) ||
      t.slug.toLowerCase().includes(q) ||
      t.keywords.some((k) => k.includes(q))
  );
}
